"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["92511"],{12624(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>p,contentTitle:()=>c,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/onboarding/endpoints/onboarding-validate","title":"Validate participant creation","description":"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.","source":"@site/docs/nhcx/v1/api/onboarding/endpoints/onboarding-validate.mdx","sourceDirName":"nhcx/v1/api/onboarding/endpoints","slug":"/nhcx/v1/api/onboarding/endpoints/onboarding-validate","permalink":"/docs/pr-33/docs/nhcx/v1/api/onboarding/endpoints/onboarding-validate","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Validate participant creation","sidebar_label":"Validate participant creation","sidebar_class_name":"api-method api-method--get","description":"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-onboarding.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the HEM-entity participant create","permalink":"/docs/pr-33/docs/nhcx/v1/api/onboarding/endpoints/onboarding-v2-participant-hementity-create"},"next":{"title":"Validate participant update","permalink":"/docs/pr-33/docs/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate"}}'),r=a(62540),i=a(43023),s=a(85030),o=JSON.parse('{"id":"onboarding_validate","module":"Onboarding","moduleId":"onboarding","kind":"operation","method":"GET","path":"/validate","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Validate participant creation","title":"Validate participant creation","description":"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.\\n\\n### Business purpose\\n\\nRegistering an organisation on a national claims exchange must be authorised by someone who actually controls that organisation\'s registered contact channel. The create call therefore only stages the record and sends a passcode to the mobile number held in HFR or the NHCX payer details; this validation call closes the loop by proving possession of that passcode. It is step 2 of the four-step production onboarding sequence and is what turns a staged participant into a confirmed one.\\n\\n### When to use\\n\\nCall it after `/v2/participant/create` returns a `transactionid` and the passcode arrives by SMS. Do it within 24 hours, and before any `/v2/participant/update`.\\n\\n### Preconditions\\n\\n- You have the `transactionid` from the create call.\\n- You have the SMS passcode for that same transaction.\\n- You have a valid access token.\\n\\n### Postconditions\\n\\nThe participant is confirmed in the registry. You can now upload the certificate and callback URL with `/v2/participant/update`.\\n\\n### Common mistakes\\n\\n- Waiting more than 24 hours, so both values expire.\\n- Calling create again while a passcode is pending, which replaces the earlier pair.\\n- Calling `/update/validate` instead. That one confirms updates.\\n\\n### Best practices\\n\\n- Treat the passcode like a one-time credential: never log it, and hand it from the phone holder to the integrator through a controlled channel.\\n- Store transactionid with a 24-hour expiry so the operator dashboard can show whether confirmation is still possible.\\n- Send parameters as query string values on a GET; there is no JSON body.\\n- After success, proceed straight to /v2/participant/update so the certificate and endpoint are in place before any counterparty tries to fetch them.\\n\\n### Related scenario\\n\\nA hospital\'s production onboarding started with /v2/participant/create, which returned transactionid 1vouv8tlz2tnl-1fpspjhwj07c6 and triggered a passcode to the medical superintendent\'s registered phone. The superintendent reads the passcode to the integration engineer, who calls GET /validate?transactionId=1vouv8tlz2tnl-1fpspjhwj07c6&passcode=482913 with the Bearer token. The registry returns 200 and the participant is confirmed. The engineer then calls /v2/participant/update with the Base64 certificate and callback URL, and completes that change with /update/validate.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[{"name":"transactionId","required":true,"description":"","type":"string","example":"<transaction id>"},{"name":"passcode","required":true,"description":"","type":"string","example":"<passcode>"}],"body":[],"responses":[{"status":"200","description":"HTTP 200 with a bare string body; the OpenAPI declares the 200 response type as string and the operation (particiapntValidate) as validating approval from the participant for participant creation.","example":{"_contentType":"string","_body":"<confirmation string as declared by the OpenAPI 200 response>"}}],"curl":"curl --request GET \\\\\\n  --url \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\" \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\" \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\"))\\n    .header(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\")\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .method(\\"GET\\", HttpRequest.BodyPublishers.noBody())\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'GET\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\',\\n        \'bearer_auth: Bearer <access token>\',\\n    ],\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n)\\n\\nfunc main() {\\n\\treq, err := http.NewRequest(\\"GET\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\", nil)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\")\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"GET\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\')\\nrequest = Net::HTTP::Get.new(uri)\\nrequest[\'Authorization\'] = \'Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\'\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Validate participant creation",sidebar_label:"Validate participant creation",sidebar_class_name:"api-method api-method--get",description:"Confirms a participant creation by presenting the SMS passcode and the transactionId returned by /v2/participant/create.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-onboarding.yaml",generated:!0},c,d={},h=[];function l(e){return(0,r.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}}}]);